      cursorKey: next_cursor
      limitParam: limit
      cursorParam: cursor
      hasMoreKey: has_more
      startingAfterParam: starting_after
      endingBeforeParam: ending_before
    error:
      code: $status
      type: $code
      message: $message
entities:
  category:
    description: Pet category such as Dogs or Cats. Spec schema Category.
    idPrefix: cat
    fields:
      name:
        type: string
        description: Category name, such as Dogs.
        required: true
        nullable: false
        unique: false
        readonly: false
        maxLength: 100
  pet:
    description: A pet listed for sale. Status moves available, pending, sold. Spec field names photoUrls, category, tags and status are kept.
    idPrefix: pet
    fields:
      name:
        type: string
        required: true
        nullable: false
        unique: false
        readonly: false
        maxLength: 200
      photoUrls:
        type: text
        description: Comma-separated photo URLs (spec array of strings).
        required: true
        nullable: false
        unique: false
        readonly: false
      category:
        type: ref
        description: The pet's category.
        required: false
        nullable: true
        unique: false
        readonly: false
        entity: category
        onDelete: nullify
      tags:
        type: text
        description: Comma-separated tag names (spec array of Tag).
        required: false
        nullable: true
        unique: false
        readonly: false
      status:
        type: state
        description: Pet status in the store. New pets are always available.
        required: false
        nullable: false
        unique: false
        readonly: false
        states:
          - available
          - pending
          - sold
        initial: available
        transitions:
          available:
            - pending
            - sold
          pending:
            - available
            - sold
          sold:
            - available
  store_order:
    description: A purchase order for a pet. Spec schema Order. Status moves placed, approved, delivered. complete is true once delivered.
    idPrefix: ord
    fields:
      petId:
        type: ref
        description: The ordered pet.
        required: true
        nullable: false
        unique: false
        readonly: false
        entity: pet
        onDelete: restrict
      quantity:
        type: int
        required: true
        nullable: false
        unique: false
        readonly: false
        min: 1
      shipDate:
        type: datetime
        description: Planned ship date.
        required: false
        nullable: true
        unique: false
        readonly: false
      status:
        type: state
        description: Order status. Set by the place, approve and deliver actions.
        required: false
        nullable: false
        unique: false
        readonly: true
        states:
          - placed
          - approved
          - delivered
        initial: placed
        transitions:
          placed:
            - approved
          approved:
            - delivered
          delivered: []
      complete:
        type: bool
        description: True once the order is delivered.
        required: false
        nullable: false
        unique: false
        readonly: true
        default: false
  refund:
    description: A refund claim on a delivered store order. Status moves requested, then approved or rejected. Holds the amount in USD minor units, the customer's reason, whether the pet was restocked, and the decision note and time.
    idPrefix: rfd
    fields:
      orderId:
        type: ref
        description: The delivered order being refunded.
        required: true
        nullable: false
        unique: false
        readonly: false
        entity: store_order
        onDelete: restrict
      amount:
        type: money
        description: Refund amount in USD minor units, at least 1.
        required: true
        nullable: false
        unique: false
        readonly: false
        currency: USD
        min: 1
      reason:
        type: text
        description: The customer's reason for the refund.
        required: true
        nullable: false
        unique: false
        readonly: false
      status:
        type: state
        description: Refund status. Set by the request, approve and reject actions.
        required: false
        nullable: false
        unique: false
        readonly: true
        states:
          - requested
          - approved
          - rejected
        initial: requested
        transitions:
          requested:
            - approved
            - rejected
          approved: []
          rejected: []
      restock:
        type: bool
        description: True when approval put the sold pet back on sale.
        required: false
        nullable: false
        unique: false
        readonly: true
        default: false
      decision_note:
        type: text
        description: Note recorded when the refund is rejected.
        required: false
        nullable: true
        unique: false
        readonly: true
      decided_at:
        type: datetime
        description: When the refund was approved or rejected. Null while requested.
        required: false
        nullable: true
        unique: false
        readonly: true
