actions:
  update_pet:
    method: PUT
    path: /pet
    description: Update an existing pet by the id in the body. A pet with an open order cannot change status.
    input:
      id:
        type: string
        description: Id of the pet to update.
        required: true
        nullable: false
        unique: false
        readonly: false
      name:
        type: string
        required: true
        nullable: false
        unique: false
        readonly: false
        maxLength: 200
      photoUrls:
        type: text
        required: true
        nullable: false
        unique: false
        readonly: false
      category:
        type: ref
        required: false
        nullable: true
        unique: false
        readonly: false
        entity: category
        onDelete: restrict
      tags:
        type: text
        required: false
        nullable: true
        unique: false
        readonly: false
      status:
        type: enum
        required: false
        nullable: true
        unique: false
        readonly: false
        values:
          - available
          - pending
          - sold
    handler: |-
      (ctx) => {
        const pet = ctx.db.get('pet', ctx.body.id);
        if (pet === null) ctx.fail(404, 'pet_not_found', 'pet ' + ctx.body.id + ' not found');
        const patch = { name: ctx.body.name, photoUrls: ctx.body.photoUrls };
        if (ctx.body.category !== undefined) patch.category = ctx.body.category;
        if (ctx.body.tags !== undefined) patch.tags = ctx.body.tags;
        const st = ctx.body.status;
        if (st !== undefined && st !== null && st !== pet.status) {
          const open = ctx.db.list('store_order', { where: { petId: pet.id } }).filter((o) => o.status === 'placed' || o.status === 'approved');
          if (open.length > 0) ctx.fail(409, 'pet_reserved', 'pet ' + pet.id + ' has an open order and stays pending. Delete the order first.');
          patch.status = st;
        }
        const updated = ctx.db.update('pet', pet.id, patch);
        return { status: 200, body: updated };
      }
  place_order:
    method: POST
    path: /store/orders
    description: Place an order for an available pet. The order starts placed and the pet becomes pending.
    input:
      petId:
        type: ref
        required: true
        nullable: false
        unique: false
        readonly: false
        entity: pet
        onDelete: restrict
      quantity:
        type: int
        required: true
        nullable: false
        unique: false
        readonly: false
        min: 1
      shipDate:
        type: datetime
        required: false
        nullable: true
        unique: false
        readonly: false
      status:
        type: enum
        required: false
        nullable: true
        unique: false
        readonly: false
        values:
          - placed
          - approved
          - delivered
      complete:
        type: bool
        required: false
        nullable: true
        unique: false
        readonly: false
    handler: |-
      (ctx) => {
        const b = ctx.body;
        if (b.status !== undefined && b.status !== null && b.status !== 'placed') ctx.fail(422, 'invalid_status', 'new orders are always placed, got ' + b.status);
        if (b.complete === true) ctx.fail(422, 'invalid_status', 'new orders cannot be complete');
        const pet = ctx.db.get('pet', b.petId);
        if (pet === null) ctx.fail(400, 'input.invalid', 'pet ' + b.petId + ' not found');
        if (pet.status !== 'available') ctx.fail(409, 'pet_not_available', 'pet ' + pet.id + ' is ' + pet.status + ', only available pets can be ordered.');
        const data = { petId: pet.id, quantity: b.quantity, complete: false };
        if (b.shipDate !== undefined) data.shipDate = b.shipDate;
        const order = ctx.db.create('store_order', data);
        ctx.db.update('pet', pet.id, { status: 'pending' });
        return { status: 200, body: order };
      }
  approve_order:
    method: POST
    path: /store/orders/{id}/approve
    description: Move a placed order to approved.
    input: {}
    handler: |-
      (ctx) => {
        const o = ctx.db.get('store_order', ctx.params.id);
        if (o === null) ctx.fail(404, 'order_not_found', 'order ' + ctx.params.id + ' not found');
        if (o.status !== 'placed') ctx.fail(409, 'invalid_state', 'order ' + o.id + ' is ' + o.status + '. Only placed orders can be approved.');
        const updated = ctx.db.update('store_order', o.id, { status: 'approved' });
        return { status: 200, body: updated };
      }
  deliver_order:
    method: POST
    path: /store/orders/{id}/deliver
    description: Move an approved order to delivered, set complete and mark the pet sold.
    input: {}
    handler: |-
      (ctx) => {
        const o = ctx.db.get('store_order', ctx.params.id);
        if (o === null) ctx.fail(404, 'order_not_found', 'order ' + ctx.params.id + ' not found');
        if (o.status !== 'approved') ctx.fail(409, 'invalid_state', 'order ' + o.id + ' is ' + o.status + '. Only approved orders can be delivered.');
        const updated = ctx.db.update('store_order', o.id, { status: 'delivered', complete: true });
        ctx.db.update('pet', o.petId, { status: 'sold' });
        return { status: 200, body: updated };
      }
  delete_order:
    method: DELETE
    path: /store/orders/{id}
    description: Delete an order. A placed or approved order releases its pet back to available.
    input: {}
    handler: |-
      (ctx) => {
        const o = ctx.db.get('store_order', ctx.params.id);
        if (o === null) ctx.fail(404, 'order_not_found', 'order ' + ctx.params.id + ' not found');
        if (o.status !== 'delivered') {
          const pet = ctx.db.get('pet', o.petId);
          if (pet !== null && pet.status === 'pending') ctx.db.update('pet', pet.id, { status: 'available' });
        }
        ctx.db.delete('store_order', o.id);
        return { status: 204, body: null };
      }
  get_inventory:
    method: GET
    path: /store/inventory
    description: Count of pets by status.
    input: {}
    handler: |-
      (ctx) => {
        const inv = { available: 0, pending: 0, sold: 0 };
        for (const p of ctx.db.list('pet')) inv[p.status] += 1;
        return { status: 200, body: inv };
      }
  request_refund:
    method: POST
    path: /store/orders/{id}/refunds
    description: Request a refund for a delivered order. One active refund (requested or approved) per order.
    input:
      amount:
        type: money
        description: Refund amount in USD minor units.
        required: true
        nullable: false
        unique: false
        readonly: false
        currency: USD
        min: 1
      reason:
        type: text
        description: Why the customer wants a refund.
        required: true
        nullable: false
        unique: false
        readonly: false
    handler: |-
      (ctx) => {
        const o = ctx.db.get('store_order', ctx.params.id);
        if (o === null) ctx.fail(404, 'order_not_found', 'order ' + ctx.params.id + ' not found');
        if (o.status !== 'delivered') ctx.fail(409, 'invalid_state', 'order ' + o.id + ' is ' + o.status + '. Only delivered orders can be refunded.');
        const reason = ctx.body.reason.trim();
        if (reason === '') ctx.fail(400, 'input.invalid', 'Invalid input for request_refund: reason expected a non-blank text');
        const active = ctx.db.list('refund', { where: { orderId: o.id } }).filter((r) => r.status === 'requested' || r.status === 'approved');
        if (active.length > 0) ctx.fail(409, 'refund_exists', 'order ' + o.id + ' already has an active refund ' + active[0].id + '.');
        const refund = ctx.db.create('refund', { orderId: o.id, amount: ctx.body.amount, reason, restock: false });
        return { status: 201, body: refund };
      }
  approve_refund:
    method: POST
    path: /refunds/{id}/approve
    description: Approve a requested refund. With restock true the sold pet goes back to available.
    input:
      restock:
        type: bool
        description: Put the sold pet back on sale. Default false.
        required: false
        nullable: true
        unique: false
        readonly: false
    handler: |-
      (ctx) => {
        const r = ctx.db.get('refund', ctx.params.id);
        if (r === null) ctx.fail(404, 'refund_not_found', 'refund ' + ctx.params.id + ' not found');
        if (r.status !== 'requested') ctx.fail(409, 'invalid_state', 'refund ' + r.id + ' is ' + r.status + '. Only requested refunds can be approved.');
        const restock = ctx.body.restock === true;
        if (restock) {
          const o = ctx.db.get('store_order', r.orderId);
          const pet = o === null ? null : ctx.db.get('pet', o.petId);
          if (pet === null || pet.status !== 'sold') ctx.fail(409, 'cannot_restock', 'the pet of order ' + r.orderId + ' is not sold, so it cannot be restocked.');
          ctx.db.update('pet', pet.id, { status: 'available' });
        }
        const updated = ctx.db.update('refund', r.id, { status: 'approved', restock, decided_at: ctx.now() });
        return { status: 200, body: updated };
      }
  reject_refund:
    method: POST
    path: /refunds/{id}/reject
    description: Reject a requested refund with a required note.
    input:
      note:
        type: text
        description: Why the refund is rejected.
        required: true
        nullable: false
        unique: false
        readonly: false
    handler: |-
      (ctx) => {
        const r = ctx.db.get('refund', ctx.params.id);
        if (r === null) ctx.fail(404, 'refund_not_found', 'refund ' + ctx.params.id + ' not found');
        const note = ctx.body.note.trim();
        if (note === '') ctx.fail(400, 'input.invalid', 'Invalid input for reject_refund: note expected a non-blank text');
        if (r.status !== 'requested') ctx.fail(409, 'invalid_state', 'refund ' + r.id + ' is ' + r.status + '. Only requested refunds can be rejected.');
        const updated = ctx.db.update('refund', r.id, { status: 'rejected', decision_note: note, decided_at: ctx.now() });
        return { status: 200, body: updated };
      }
