  release_stale_placed_orders:
    difficulty: hard
    instruction: Delete every order that is still in status placed (never approved) and whose shipDate is before 2026-10-07, so that their pets return to available. Leave approved and delivered orders, and placed orders with a later ship date, alone. Change nothing else.
    grader: |-
      (ctx) => {
        const cutoff = '2026-10-07T00:00:00.000Z';
        const targets = ctx.seed.list('store_order', { where: { status: 'placed' } })
          .filter((o) => o.shipDate !== null && ctx.time.minutesBetween(o.shipDate, cutoff) > 0);
        if (targets.length === 0) return 0;
        const fields = ['petId', 'quantity', 'shipDate', 'status', 'complete'];
        ctx.guardChanges('only the stale placed orders were deleted and their pets released', [
          ...targets.map((o) => ({ entity: 'store_order', id: o.id, kind: 'deleted', fields })),
          ...targets.map((o) => ({ entity: 'pet', id: o.petId, kind: 'updated', fields: ['status'] })),
        ]);
        for (const o of targets) {
          const gone = ctx.db.get('store_order', o.id) === null;
          const pet = ctx.db.get('pet', o.petId);
          ctx.goal(1 / targets.length, 'order ' + o.id + ' deleted and its pet available', gone && pet !== null && pet.status === 'available');
        }
        return ctx.score();
      }
    solution: |-
      (ctx) => {
        const cutoff = '2026-10-07T00:00:00.000Z';
        const rows = [];
        let cursor = null;
        do {
          const r = ctx.api('GET', '/store/orders?status=placed' + (cursor === null ? '' : '&cursor=' + cursor));
          ctx.assert(r.status === 200, 'list failed: ' + JSON.stringify(r.body));
          rows.push(...r.body.data);
          cursor = r.body.next_cursor;
        } while (cursor !== null);
        const stale = rows.filter((o) => o.shipDate !== null && o.shipDate < cutoff);
        ctx.assert(stale.length > 0, 'no stale placed orders found');
        for (const o of stale) {
          const r = ctx.api('DELETE', '/store/orders/' + o.id);
          ctx.assert(r.status === 204, 'delete ' + o.id + ' failed: ' + JSON.stringify(r.body));
        }
      }
    decoys:
      - why: deletes only the first stale placed order and stops, leaving the others
        script: |-
          (ctx) => {
            const rows = ctx.api('GET', '/store/orders?status=placed').body.data;
            const stale = rows.filter((o) => o.shipDate !== null && o.shipDate < '2026-10-07T00:00:00.000Z');
            ctx.api('DELETE', '/store/orders/' + stale[0].id);
          }
      - why: deletes every order with a past ship date, including the approved one
        script: |-
          (ctx) => {
            const rows = ctx.api('GET', '/store/orders').body.data;
            const stale = rows.filter((o) => o.shipDate !== null && o.shipDate < '2026-10-07T00:00:00.000Z' && o.status !== 'delivered');
            for (const o of stale) ctx.api('DELETE', '/store/orders/' + o.id);
          }
      - why: deletes all placed orders including the future-dated ones
        script: |-
          (ctx) => {
            const rows = ctx.api('GET', '/store/orders?status=placed').body.data;
            for (const o of rows) ctx.api('DELETE', '/store/orders/' + o.id);
          }
